window.__finlexDocLoaded(10074,{"id":10074,"articles":[{"id":1000345,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"SIC-25 clarifies that an entity recognises the current and deferred tax consequences of the change in the tax status of the entity or its shareholders in profit or loss in the period the change occurs. Those consequences are not recognised directly in shareholders’ equity.","seq":0},{"id":1000346,"no":"History","heading":"Standard History & Amendments","text":"In April 2001 the International Accounting Standards Board adopted SIC‑25 Income Taxes—Changes in the Tax Status of an Entity or its Shareholders, which had originally been issued by the Standing Interpretations Committee of the International Accounting Standards Committee in July 2000.","seq":1},{"id":1000347,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related active projects]\n[Related completed projects]\n[Related IFRS Standards]\nIAS 12 Income Taxes\n[Related IFRIC Interpretations]\n[Unconsolidated amendments]\n[Implementation support]","seq":2},{"id":1000348,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/sic-25-income-taxes-changes-in-the-tax-status-of-an-entity-or-its-shareholders/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":3}]});
